head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gReqAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF30205.xml';
scwin.key_acpt_no; //팝업 시 key값으로 전달 할 변수(접수번호)
scwin.key_reg_yn; //팝업 시 등록 or 수정 판단을 위한 변수(조회공시요구서등록여부)
scwin.key_mkt_nm;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //팝업 시 활용될 시장구분 코드이름

//2016.10.10 KBoY isur_cd 추가
scwin.fn_setKey = function(acpt_no, reg_yn, mkt_nm, isur_cd) {
    scwin.key_acpt_no = acpt_no;
    scwin.key_reg_yn = reg_yn;
    scwin.key_mkt_nm = mkt_nm;
    key_isur_cd = isur_cd;
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.stf.showObj(panel_mkt, false);
    }

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = "20010101"  //2001 이후 데이터만 존재하므로 from을 20010101로 세팅(YSH, 2008/09/05)
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 30)); // 1달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();



    // 유가일때만 초기 검색함
    //if (js_market == '1' ) {		
    fn_CheckCond();
    //}


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !조회공시--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !조회공시--;
클릭-- > function() {
    var url_list = "/InquiryDisclosure.do?method=listInquiryDsclRequest&inputMessageId=INQDISCLSCOND_IN" + "&outputMessageId=INQDISCLSREQLIST_OUT";
    var url_cond = "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_InqDsclList.DataID = encodeURI(url_list + url_cond);
    dts_InqDsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gReqAcptNo = dts_InqDsclList.getCellData(eval(obj), "REQ_ACPT_NO");
    scwin.gIsurCd = dts_InqDsclList.getCellData(eval(obj), "ISUR_CD");
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "CONTN_TP_CD") {
        //Key 값 셋팅
        scwin.fn_setKey(dts_InqDsclList.getCellData(row, "REQ_ACPT_NO"), dts_InqDsclList.getCellData(row, "REG_YN"), dts_InqDsclList.getCellData(row, "MKT_ID"), dts_InqDsclList.getCellData(row, "ISUR_CD"));

        //팝업창 정보
        var url = "/dsclmgt/ULDSTF30206.gfm";
        var winTitle = "";
        if (dts_InqDsclList.getCellData(row, "REG_YN") == 'Y') {
            winTitle = "조회공시요구서 생성 및 관리(수정)";
        } else {
            winTitle = "조회공시요구서 생성 및 관리(등록)";
        }
        await $c.frame.CreateDialogFrame("ULDSTF30205", url, winTitle, 200, 10, 715, 500, "window");
    } else if (colid == "REQ_DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(dts_InqDsclList.getCellData(row, "REQ_ACPT_NO"), 'R');
    }
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.dts_InqDsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_InqDsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_InqDsclList_OnLoadCompleted = function(rowcount) {
    if (dts_InqDsclList.errorMsg) {
        $c.win.alert(dts_InqDsclList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	
    if (js_market == '1') {
        $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
    }
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	
    if (js_market == '1') {
        $c.stf.setObjectValue(cmb_EmpList, js_emp_no);
    }
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "조회공시요구 목록", "", "2");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
